    (hf : ContDiffOn ℝ ∞ f U) (hg : ContDiffOn ℝ ∞ g U) (l : List P) :
    EqOn (jet (fun p => f p + g p) l) (fun p => jet f l p + jet g l p) U

theorem jet_clm {U : Set P} (hU : IsOpen U) {f : P → E}
    (hf : ContDiffOn ℝ ∞ f U) (L : E →L[ℝ] F) (l : List P) :
