theorem physicalChart_eq {a Q : ℝ} (ha : 0 < a) (hQ : 0 < Q) (j : Index) {p : Plane}
    (hp : scalePlane Q p ∈ chartDomain a j) :
    physicalChart a j Q p = (radius p / Real.sqrt Q, (localChart j p).2)

theorem physicalChart_inverse {a Q : ℝ} (ha : 0 < a) (hQ : 0 < Q) (j : Index) {p : Plane}
    (hp : scalePlane Q p ∈ chartDomain a j) :
    Real.sqrt Q • polar (physicalChart a j Q p) = p

theorem bandChart_jet_bound {V : Type} [NormedAddCommGroup V] [NormedSpace ℝ V]
    {f : SlowPoint → V} (hf : ContDiff ℝ ∞ f) (D : ℝ) {n m : ℕ}
