    (hb : ∀ j ≤ r, ‖iteratedFDeriv ℝ j f (bandChart D n m x)‖ ≤ A) :
    ∀ j ≤ r, ‖iteratedFDeriv ℝ j (fun y => f (bandChart D n m y)) x‖ ≤ A * chartCost D ^ r

theorem currentArgument_jet_bound (g : CCS) (k : Frequency) {f : Joint P → V}
