    scalarLaplacian (fun y => L (f y)) q = L (scalarLaplacian f q)

theorem scalarLaplacian_pullback {f : Space → E} {q : Space}
    (hf : ContDiffAt ℝ 2 f (chart q)) (hr : q 0 ≠ 0) :
    scalarLaplacian (fun y => f (chart y)) q = euclideanLaplacian f (chart q)

